using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

namespace RestApiMcpServer.Tools;

// Non-static class: HttpClient and ILogger are constructor-injected via DI.
// They do NOT appear in the tool schema — only [Description] parameters do.
[McpServerToolType]
public class UserApiTools(HttpClient httpClient, ILogger<UserApiTools> logger)
{
    [McpServerTool, Description("Look up a user by their numeric ID.")]
    public async Task<string> GetUser(
        [Description("The user's numeric ID")] int userId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching user {UserId}", userId);

        var user = await httpClient.GetFromJsonAsync<User>(
            $"/users/{userId}", cancellationToken);

        return user is null
            ? $"No user found with ID {userId}."
            : $"Name: {user.Name}\nEmail: {user.Email}\nCompany: {user.Company?.Name}";
    }

    [McpServerTool, Description("Search for users whose name contains a keyword.")]
    public async Task<string> SearchUsers(
        [Description("Keyword to match against user names")] string keyword,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Searching users with keyword '{Keyword}'", keyword);

        var users = await httpClient.GetFromJsonAsync<List<User>>(
            "/users", cancellationToken) ?? [];

        var matches = users
            .Where(u => u.Name?.Contains(keyword, StringComparison.OrdinalIgnoreCase) == true)
            .ToList();

        return matches.Count == 0
            ? "No matching users found."
            : string.Join("\n", matches.Select(u => $"[{u.Id}] {u.Name} ({u.Email})"));
    }

    [McpServerTool, Description("List all users from the API.")]
    public async Task<string> ListUsers(CancellationToken cancellationToken = default)
    {
        var users = await httpClient.GetFromJsonAsync<List<User>>(
            "/users", cancellationToken) ?? [];

        return string.Join("\n", users.Select(u => $"[{u.Id}] {u.Name}"));
    }
}

// DTOs for the JSONPlaceholder /users endpoint
public record User
{
    [JsonPropertyName("id")]    public int Id { get; init; }
    [JsonPropertyName("name")]  public string? Name { get; init; }
    [JsonPropertyName("email")] public string? Email { get; init; }
    [JsonPropertyName("company")] public Company? Company { get; init; }
}

public record Company
{
    [JsonPropertyName("name")] public string? Name { get; init; }
}

